    const focused = focusedChecks();
    const counts = { X_WIN: 0, O_WIN: 0, O_KOMI: 0, draws: 0, total: 0 };
    let visitedNodes = 0;
    let maxDepth = 0;
    const path = [];

    function verify(condition, message) {
      if (!condition) throw new Error(`${message}; move sequence: [${path.join(", ")}]`);
    }

